-- Preserve this week's goals and earned progress; start the weekly catalog next Monday UTC.
begin;
create table academy_progression_private.weekly_catalog (
 id text primary key, position integer not null unique check(position between 0 and 99), title text not null,
 description text not null, metric text not null check(metric in ('correct','answers','sessions','days','accurate','perfect','modes','filters','comeback','improve','accurate_correct','balanced')),
 target integer not null check(target>0), xp integer not null check(xp between 100 and 500),
 game_mode text check(game_mode in ('study_test','matching','speed','blaster')),
 code_filter text check(code_filter in ('penal','hs','vehicle')),
 min_accuracy integer not null default 0 check(min_accuracy between 0 and 100), min_answers integer not null default 5 check(min_answers>=5),
 practice_path text not null check(practice_path in ('/study/test','/games/matching','/games/speed','/games/blaster')), category text not null,
 balanced_correct integer not null default 10 check(balanced_correct>0)
);
alter table academy_progression_private.weekly_catalog enable row level security;
alter table academy_progression_private.rotation_config add column weekly_starts_on date not null default ((date_trunc('week',now() at time zone 'UTC'))::date+7);
alter table academy_progression_private.rotation_config add constraint weekly_rotation_monday check(extract(isodow from weekly_starts_on)=1);
insert into academy_progression_private.weekly_catalog
